//! Replays the state file's share of the oracle corpus: every case of a kind
//! this crate answers must get the answer upstream's TypeScript gave,
//! compared as text. The corpus is regenerated by `tools/oracle/refresh.sh`;
//! nothing here needs upstream or Bun.

use std::fs;
use std::path::Path;

use focus_js::json::stringify;
use focus_state::oracle::{KINDS, run_case};
use serde_json::{Value, json};

#[test]
fn every_state_case_gets_upstreams_answer() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.lines().filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.lines().filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );

    let (mut replayed, mut with_boxes, mut with_actions) = (0, 0, 0);
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        // Parsed as upstream's driver parses it, so nested objects are in the
        // order a JS object enumerates them.
        let case: Value = focus_js::json::parse(line).unwrap();
        if !KINDS.contains(&case["kind"].as_str().unwrap_or_default()) {
            continue;
        }
        replayed += 1;
        let out = run_case(&case);
        with_boxes += usize::from(
            out["checkboxes"]
                .as_array()
                .is_some_and(|boxes| boxes.len() > 1),
        );
        with_actions += usize::from(
            out["suffixes"]
                .as_array()
                .is_some_and(|actions| !actions.is_empty()),
        );
        let got = stringify(&json!({ "id": case["id"], "out": out }));
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    // Enough cases, and enough of them with something in them.
    assert!(replayed >= 100, "too few state cases: {replayed}");
    assert!(
        with_boxes >= 50 && with_actions >= 50,
        "{with_boxes} {with_actions}"
    );
    assert!(
        differing.is_empty(),
        "{} state cases differ from upstream; first:\n{}",
        differing.len(),
        differing
            .iter()
            .take(3)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
